python3 - << 'EOF'
import re, subprocess, sys, collections

root = "."
files = subprocess.run(["find", root, "-name", "*.c"], capture_output=True, text=True).stdout.split()

candidates = []
for fn in files:
    try:
        with open(fn, errors="ignore") as f:
            src = f.read()
    except Exception:
        continue
    # find functions
    for m in re.finditer(r'^[A-Za-z_][A-Za-z0-9_ \t\*]*\(\s*$|^static.*?\)\s*$|^[A-Za-z_].*\(.*\)\s*\{', src, re.M):
        pass
    # simpler: split by function definition heuristics using lines
    lines = src.split("\n")
    # locate top-level function starts: line matching r'^[a-zA-Z_].*\(.*$' with following line ending '{' or same-line '{'
    fstarts = []
    for i, line in enumerate(lines):
        if re.match(r'^(static\s+)?(inline\s+)?(const\s+)?(struct\s+\w+\s*\*+\s*|[A-Za-z_][A-Za-z0-9_]*\s+\*?)[a-zA-Z_0-9]*\s*\(', line):
            # search forward for '{' within 6 lines at paren depth 0
            depth = 0; seen = False
            for j in range(i, min(i+8, len(lines))):
                for ch in lines[j]:
                    if ch == '(': depth += 1; seen = True
                    elif ch == ')': depth -= 1
                if seen and depth == 0 and '{' in lines[j]:
                    fstarts.append((i, j)); break
    for k, (ls, le) in enumerate(fstarts):
        end = fstarts[k+1][0] if k+1 < len(fstarts) else len(lines)
        body = "\n".join(lines[ls:end])
        has_realloc = re.search(r'\b(skb_cow_head|skb_cow|skb_unclone|skb_share_check|pskb_expand_head|skb_linearize)\s*\(', body)
        if not has_realloc:
            continue
        # capture: var = (struct x *)skb->data / skb_network_header / skb_header_pointer / ip_hdr / etc
        # collect pointer-variable captures and post-cow dereferences
        # find first cow call line index within body
        for cm in re.finditer(r'\b(skb_cow_head|skb_cow|skb_unclone|skb_share_check|pskb_expand_head|skb_linearize)\s*\(([^;]*)\)', body):
            cow_line_off = body[:cm.start()].count("\n")
            pre = body[:cm.start()]
            post = body[cm.end():]
            # captures of pointers into skb
            capvars = set()
            for c in re.finditer(r'\b([A-Za-z_][A-Za-z0-9_]*)\s*=\s*(?:\([A-Za-z_ ]*[\s\*]\)\s*)?(skb_header_pointer\s*\(|skb_network_header\s*\(|skb_mac_header\s*\(|skb_transport_header\s*\(|ip_hdr\s*\(|ipv6_hdr\s*\(|tcp_hdr\s*\(|udp_hdr\s*\(|icmp_hdr\s*\(|igmp_hdr\s*\(|skb->data|skb->head|skb_tail_pointer|eth_hdr\s*\()', pre):
                capvars.add(c.group(1))
            if not capvars:
                continue
            # check uses of those vars after cow call
            used = []
            for v in capvars:
                for um in re.finditer(r'\b' + re.escape(v) + r'\b\s*(->|\[|\.|\)|,|\+|;|\))', post):
                    used.append((v, um.start()))
            if used:
                candidates.append((fn, ls + cow_line_off + 1, cm.group(1), sorted(capvars), sorted(set(v for v,_ in used))))

print(len(candidates), "raw candidates")
for c in candidates:
    print("%s:%d %s caps=%s used=%s" % (c[0], c[1], c[2], c[3], c[4]))
EOF

